"""Remote archive maintenance payload; contains no credentials."""
ARCHIVE_SOURCE = '"""Restricted removal of completed TelegramOnly reset archives on Debian."""\nimport fcntl\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport re\nimport shutil\nimport socket\nimport stat\nimport sys\n\nBASE = Path(\'/var/backups/telegramonly-reset\')\nNAME = re.compile(r\'[0-9]{8}-[0-9]{6}-[a-f0-9]{12}\')\n\ndef inventory():\n    if not BASE.exists():\n        if BASE.is_symlink():\n            raise ValueError(\'Unsafe backup directory\')\n        return []\n    if BASE.resolve() != BASE or not BASE.is_dir():\n        raise ValueError(\'Unsafe backup directory\')\n    info = BASE.stat()\n    if info.st_uid != 0 or info.st_mode & 0o077:\n        raise ValueError(\'Backup directory must be root-only\')\n    mount_data = json.loads(__import__(\'subprocess\').check_output(\n        [\'findmnt\', \'--json\', \'--list\', \'--output\', \'TARGET\'], timeout=30))\n    mounts = [m[\'target\'] for m in mount_data.get(\'filesystems\', [])]\n    result = []\n    for directory in sorted(BASE.iterdir()):\n        if not NAME.fullmatch(directory.name) or directory.is_symlink() or not directory.is_dir():\n            continue\n        manifest = directory / \'manifest.json\'\n        if manifest.is_symlink() or not manifest.is_file() or manifest.stat().st_size > 2 * 1024 * 1024:\n            continue\n        metadata = json.loads(manifest.read_text(encoding=\'utf-8\'))\n        if metadata.get(\'status\') != \'complete\':\n            continue\n        # WARNING: archive data may contain links or mounts; never follow them when deleting.\n        if any(m == str(directory) or m.startswith(str(directory) + \'/\') for m in mounts):\n            continue\n        digest = hashlib.sha256(manifest.read_bytes())\n        size = 0\n        for current, dirs, files in os.walk(directory, followlinks=False):\n            for name in [\'.\'] + sorted(dirs + files):\n                path = Path(current) / name\n                s = path.lstat()\n                digest.update(json.dumps([str(path.relative_to(BASE)), s.st_dev, s.st_ino,\n                    s.st_mode, s.st_size, s.st_mtime_ns, s.st_ctime_ns]).encode())\n                size += s.st_blocks * 512\n        result.append({\'name\': directory.name, \'bytes\': size, \'hash\': digest.hexdigest()})\n    return result\n\ndef main():\n    if os.geteuid() != 0:\n        raise ValueError(\'Root privileges required\')\n    with open(\'/run/lock/telegramonly-reset.lock\', \'w\') as lock:\n        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)\n        archives = inventory()\n        hostname = socket.gethostname()\n        if len(sys.argv) > 1:\n            if len(sys.argv) != 4 or sys.argv[3] != hostname:\n                raise ValueError(\'Host confirmation required\')\n            match = next((a for a in archives if a[\'name\'] == sys.argv[1] and a[\'hash\'] == sys.argv[2]), None)\n            if not match:\n                raise ValueError(\'Archive changed or is not a completed reset; reload list\')\n            if not shutil.rmtree.avoids_symlink_attacks:\n                raise ValueError(\'Safe directory deletion unavailable\')\n            # Fixed root, validated single child, lock shared with reset, fd-safe rmtree.\n            shutil.rmtree(BASE / match[\'name\'])\n            print(json.dumps({\'success\': True}))\n        else:\n            print(json.dumps({\'hostname\': hostname, \'archives\': archives}))\n\nif __name__ == \'__main__\':\n    try:\n        main()\n    except Exception:\n        print(json.dumps({\'success\': False, \'error\': \'Archive operation failed; refresh the list and inspect the server. No automatic retry.\'}))\n        sys.exit(1)\n'
